import 'package:flutter/material.dart';import'../api/gaon_api.dart';class RepeatPurchasePanel extends StatefulWidget{const RepeatPurchasePanel({super.key});@override State<RepeatPurchasePanel>createState()=>_State();}class _State extends State<RepeatPurchasePanel>{List<dynamic>items=[];@override void initState(){super.initState();load();}Future<void>load()async{try{final r=await GaonApi.repeatCadence();if(mounted)setState(()=>items=List<dynamic>.from(r['items']??[]).where((x)=>x['due']==true).take(5).toList());}catch(_){}}@override Widget build(BuildContext context){if(items.isEmpty)return const SizedBox.shrink();return Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Due again',style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w700)),const Text('Based on your delivered-order rhythm.'),...items.map((x)=>ListTile(contentPadding:EdgeInsets.zero,title:Text('${x['product_name']}'),subtitle:Text('Usually every ${x['cadence_days']} days • ${x['purchase_count']} purchases'))])));}}
